# Databricks notebook source
# MAGIC %md
# MAGIC # 62 · Event maps — data layer for the "Exposure — Event maps" AI/BI dashboard
# MAGIC
# MAGIC The app's hand-drawn SVG maps are replaced by a published AI/BI (Lakeview) dashboard with **one page per
# MAGIC hero event** (`resources/dashboards/event_maps.lvdash.json`, generated by `build_event_maps.py`). Lakeview's
# MAGIC point map plots points, not polygons — so each event footprint is drawn as **fill points**: a regular grid of
# MAGIC points inside the footprint, which reads as a solid shape on the map. Homes are coloured *in the path*
# MAGIC (within 200 m, the same predicate as `fn_exposure_in_footprint`) vs *clear*.
# MAGIC
# MAGIC | Object | What it is |
# MAGIC |---|---|
# MAGIC | `mv_map_footprint_points` | Fill points for every active event footprint (adaptive density) |
# MAGIC | `mv_map_event_homes` | Homes around each event: `in_path` (≤200 m, EPSG:3035) + nearby clear context |
# MAGIC | `mv_map_live_footprint_points` | Fill points for the live-follow fire at the current `live_cursor` tick |
# MAGIC | `mv_map_uk_uw_risks` | Underwriting-workbench risks (UK postcode centroids) vs active Environment Agency zones |
# MAGIC | `mv_map_book_homes` | The whole book, flagged in the path of any active event (overview page) |
# MAGIC | `ref_dashboard_pages` | event → dashboard page + embed URL, read by the app |
# MAGIC
# MAGIC **GOTCHA:** `ST_*` does not run via `spark.sql` on serverless notebooks (Spark Connect) — everything here runs
# MAGIC on the SQL warehouse via the Statement Execution API, like notebooks 02 and 60. `CREATE OR REPLACE` drops
# MAGIC grants, so they are re-applied at the end.

# COMMAND ----------
import time, requests
dbutils.widgets.text("catalog", "lr_dev_aws_us_catalog"); dbutils.widgets.text("schema", "exposure_response")
dbutils.widgets.text("warehouse_id", "a3b61648ea4809e3")
dbutils.widgets.text("dashboard_id", "01f1c87e1f09165882526104d43e26b5")
dbutils.widgets.text("app_sp", "fc3ac835-8393-4ea6-8d2b-180096836d7b")
CATALOG = dbutils.widgets.get("catalog"); SCHEMA = dbutils.widgets.get("schema")
WH = dbutils.widgets.get("warehouse_id"); DASH = dbutils.widgets.get("dashboard_id"); APP_SP = dbutils.widgets.get("app_sp")
S = f"{CATALOG}.{SCHEMA}"
HOST = spark.conf.get("spark.databricks.workspaceUrl")
TOKEN = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()
H = {"Authorization": f"Bearer {TOKEN}"}


def run_wh(sql: str):
    """Execute one statement on the SQL warehouse (so ST_* resolves); poll to terminal."""
    r = requests.post(f"https://{HOST}/api/2.0/sql/statements", headers=H,
                      json={"warehouse_id": WH, "statement": sql, "wait_timeout": "30s",
                            "catalog": CATALOG, "schema": SCHEMA}).json()
    sid, st = r.get("statement_id"), r.get("status", {}).get("state")
    while st in ("PENDING", "RUNNING"):
        time.sleep(2)
        r = requests.get(f"https://{HOST}/api/2.0/sql/statements/{sid}", headers=H).json()
        st = r.get("status", {}).get("state")
    if st != "SUCCEEDED":
        raise RuntimeError(f"{st}: {r.get('status', {}).get('error')}\nSQL: {sql[:300]}")
    return r.get("result", {}).get("data_array") or []

# COMMAND ----------
# MAGIC %md ## Footprints as fill points
# MAGIC A regular grid over each footprint segment's bounding box, kept where the point falls inside the segment.
# MAGIC 24×24 per segment normally; 14 or 8 for events with many segments (MeteoAlarm warns by region) so the map
# MAGIC stays light.

# COMMAND ----------
run_wh(f"""
CREATE OR REPLACE VIEW {S}.mv_map_footprint_points
COMMENT 'Map-ready fill points for every active event footprint (a regular grid of points inside each footprint polygon, EPSG:4326) so a Lakeview point map draws the footprint as a shape. Adaptive density: fewer points per segment for events with many segments (e.g. MeteoAlarm warnings by region). Read by the Exposure — Event maps dashboard.'
AS
WITH seg AS (
  SELECT event_id, event_name, peril_code, source, ST_GeomFromText(footprint_wkt, 4326) AS g,
         count(*) OVER (PARTITION BY event_id) AS n_segs
  FROM {S}.`2_event_footprint`
  WHERE footprint_wkt IS NOT NULL
),
bb AS (
  SELECT event_id, event_name, peril_code, source, g,
         ST_XMin(g) AS x0, ST_XMax(g) AS x1, ST_YMin(g) AS y0, ST_YMax(g) AS y1,
         CASE WHEN n_segs > 10 THEN 8 WHEN n_segs > 3 THEN 14 ELSE 24 END AS n
  FROM seg
),
grid AS (
  SELECT event_id, event_name, peril_code, source, g,
         x0 + i * (x1 - x0) / n AS lon, y0 + j * (y1 - y0) / n AS lat
  FROM bb
  LATERAL VIEW explode(sequence(0, 24)) a AS i
  LATERAL VIEW explode(sequence(0, 24)) b AS j
  WHERE i <= n AND j <= n
)
SELECT event_id, event_name, peril_code, source, CAST(lat AS DOUBLE) AS latitude, CAST(lon AS DOUBLE) AS longitude
FROM grid
WHERE ST_Contains(g, ST_SetSRID(ST_Point(lon, lat), 4326))
""")

run_wh(f"""
CREATE OR REPLACE VIEW {S}.mv_map_live_footprint_points
COMMENT 'Fill points for the live-follow fire footprint at the current tick (2_event_progression joined to live_cursor). Moves when the app advances the cursor, so the Event maps live page redraws the spreading fire on refresh.'
AS
WITH cur AS (SELECT event_id, t_index FROM {S}.live_cursor LIMIT 1),
seg AS (
  SELECT ep.event_id, ep.t_index, ep.label, ep.as_of_ts, ep.corroborated, ST_GeomFromText(ep.footprint_wkt, 4326) AS g
  FROM {S}.`2_event_progression` ep JOIN cur ON ep.event_id = cur.event_id AND ep.t_index = cur.t_index
  WHERE ep.footprint_wkt IS NOT NULL
),
bb AS (SELECT *, ST_XMin(g) AS x0, ST_XMax(g) AS x1, ST_YMin(g) AS y0, ST_YMax(g) AS y1 FROM seg),
grid AS (
  SELECT event_id, t_index, label, as_of_ts, corroborated, g,
         x0 + i * (x1 - x0) / 30 AS lon, y0 + j * (y1 - y0) / 30 AS lat
  FROM bb LATERAL VIEW explode(sequence(0, 30)) a AS i LATERAL VIEW explode(sequence(0, 30)) b AS j
)
SELECT event_id, t_index, label, as_of_ts, corroborated, CAST(lat AS DOUBLE) AS latitude, CAST(lon AS DOUBLE) AS longitude
FROM grid WHERE ST_Contains(g, ST_SetSRID(ST_Point(lon, lat), 4326))
""")

# COMMAND ----------
# MAGIC %md ## Homes around each event
# MAGIC `in_path` uses exactly the predicate of `fn_exposure_in_footprint(event, 200)` — unioned footprint, EPSG:3035,
# MAGIC `ST_DWithin(…, 200)` — so the dashboard's counters always equal the app's numbers.

# COMMAND ----------
run_wh(f"""
CREATE OR REPLACE VIEW {S}.mv_map_event_homes
COMMENT 'Insured homes around each active event for the event maps: in_path = within 200 m of the unioned footprint in true metres (EPSG:3035) — exactly the predicate of fn_exposure_in_footprint(event, 200), so the dashboard KPIs match the app. Context homes out to 5 km (fire) / 8 km (flood) / 15 km (storm) are included as clear.'
AS
WITH ev AS (
  SELECT event_id, event_name, peril_code,
         ST_Transform(ST_Union_Agg(ST_GeomFromText(footprint_wkt, 4326)), 3035) AS g,
         CASE peril_code WHEN 'FIRE' THEN 5000 WHEN 'FLOOD' THEN 8000 ELSE 15000 END AS ctx_m
  FROM {S}.`2_event_footprint`
  WHERE footprint_wkt IS NOT NULL
  GROUP BY event_id, event_name, peril_code
),
props AS (
  SELECT insured_object_id, country_code, city, sum_insured,
         CAST(latitude AS DOUBLE) AS latitude, CAST(longitude AS DOUBLE) AS longitude,
         ST_Transform(ST_SetSRID(ST_Point(longitude, latitude), 4326), 3035) AS pg
  FROM {S}.`3_property`
)
SELECT ev.event_id, ev.event_name, ev.peril_code, p.insured_object_id, p.country_code, p.city,
       p.latitude, p.longitude, p.sum_insured,
       ST_Distance(p.pg, ev.g) AS distance_m,
       ST_DWithin(p.pg, ev.g, 200) AS in_path
FROM props p JOIN ev ON ST_DWithin(p.pg, ev.g, ev.ctx_m)
""")

run_wh(f"""
CREATE OR REPLACE VIEW {S}.mv_map_book_homes
COMMENT 'The whole Bricksurance SE property book for the Event maps overview: each home flagged in_path when it lies within 200 m (EPSG:3035) of ANY active event footprint, with the count of events touching it.'
AS
WITH ev AS (
  SELECT event_id, ST_Transform(ST_Union_Agg(ST_GeomFromText(footprint_wkt, 4326)), 3035) AS g
  FROM {S}.`2_event_footprint` WHERE footprint_wkt IS NOT NULL GROUP BY event_id
),
p AS (
  SELECT insured_object_id, country_code, city, sum_insured,
         CAST(latitude AS DOUBLE) AS latitude, CAST(longitude AS DOUBLE) AS longitude,
         ST_Transform(ST_SetSRID(ST_Point(longitude, latitude), 4326), 3035) AS pg
  FROM {S}.`3_property`
),
hit AS (SELECT p.insured_object_id, count(ev.event_id) AS n_events FROM p JOIN ev ON ST_DWithin(p.pg, ev.g, 200) GROUP BY p.insured_object_id)
SELECT p.insured_object_id, p.country_code, p.city, p.latitude, p.longitude, p.sum_insured,
       COALESCE(hit.n_events, 0) AS n_events, COALESCE(hit.n_events, 0) > 0 AS in_path
FROM p LEFT JOIN hit ON hit.insured_object_id = p.insured_object_id
""")

# COMMAND ----------
# MAGIC %md ## UK: underwriting risks vs active Environment Agency flood zones
# MAGIC The cross-workbench picture: the underwriting workbench's UK submissions (at postcode-district centroids)
# MAGIC against the UK flood zones this workbench publishes. Returns every district as clear until EA zones exist.

# COMMAND ----------
run_wh(f"""
CREATE OR REPLACE VIEW {S}.mv_map_uk_uw_risks
COMMENT 'Underwriting-workbench risks (UK SME submissions, at postcode-district centroids) against active UK Environment Agency flood zones (2_event_footprint source=EA). in_zone = the district centroid lies inside an active EA zone. Shows on the Event maps UK page which underwriting risks the published active zones touch. Returns all districts as clear until EA zones exist.'
AS
WITH z AS (
  SELECT ST_Transform(ST_Union_Agg(ST_GeomFromText(footprint_wkt, 4326)), 3035) AS g
  FROM {S}.`2_event_footprint` WHERE source = 'EA' AND footprint_wkt IS NOT NULL
),
d AS (
  SELECT s.postcode_district, count(*) AS n_submissions, sum(s.total_property_si) AS total_property_si
  FROM {CATALOG}.underwriting_workbench.silver_submissions s
  GROUP BY s.postcode_district
)
SELECT d.postcode_district, CAST(c.lat AS DOUBLE) AS latitude, CAST(c.lon AS DOUBLE) AS longitude,
       d.n_submissions, d.total_property_si,
       COALESCE(ST_Contains(z.g, ST_Transform(ST_SetSRID(ST_Point(c.lon, c.lat), 4326), 3035)), false) AS in_zone
FROM d JOIN {CATALOG}.underwriting_workbench.ref_postcode_centroid c ON c.postcode_district = d.postcode_district
CROSS JOIN z
""")

# COMMAND ----------
# MAGIC %md ## Event → dashboard page (read by the app)
# MAGIC Each event's map is its own one-widget published dashboard (`MAP_DASH`, split from the Event maps dashboard by
# MAGIC `resources/dashboards/split_event_maps.py`), embedded with the plain form `/embed/dashboardsv3/<id>?o=<wsid>`.
# MAGIC (The single-widget `fullscreenWidget=<page>~<widget>` embed loaded the frame but the map never drew — 16 Oct dry run.)
# MAGIC `event_id='*'` is the book-wide overview — the default for any event without its own page. Any `source='EA'` event
# MAGIC uses the UK page.

# COMMAND ----------
WSID = str(requests.get(f"https://{HOST}/api/2.1/unity-catalog/current-metastore-assignment", headers=H).json()["workspace_id"])
PAGES = [  # event_id, page, map widget, title
    ("EVT_LIVE_VAR_FIRE", "live", "live_map", "Var wildfire — live"),
    ("EVT_FIRE_VAR", "var", "var_map", "Var wildfire"),
    ("EVT_FLOOD_ALPS", "alps", "alps_map", "Alpine flood — one event, two countries"),
    ("EVT_STORM_CELINE", "celine", "celine_map", "Windstorm Celine"),
    ("EVT_EA_SAMPLE_UK", "uk", "uk_map", "UK flood — Environment Agency warnings"),
    ("*", "overview", "ov_map", "All active events"),
]
run_wh(f"""CREATE OR REPLACE TABLE {S}.ref_dashboard_pages (
  event_id STRING, dashboard_id STRING, page_id STRING, embed_url STRING, title STRING,
  page_url STRING, map_widget STRING)
COMMENT 'Event → its one-widget map dashboard (split from Exposure — Event maps). embed_url = plain embed of that map (iframe-ready); page_url = the published map. event_id * = overview, the default for events without their own page; source=EA events use the EVT_EA_SAMPLE_UK page.'""")
base = f"https://{HOST}"
MAP_DASH = {  # page → its one-widget map dashboard (DEV workspace)
    "live": "01f1c94f6ca21f48a78dfab076d66164",
    "var": "01f1c94f6d6c1a30b5b8c0e810a6201e",
    "alps": "01f1c94f6e38191887fbe57a45734250",
    "celine": "01f1c94f6ef8186f93cd116988e79cea",
    "uk": "01f1c94f6fbd19abbfb679b24e7279c7",
    "overview": "01f1c94f707f1db8af395ca43683d734",
}
rows = ",".join(
    f"('{e}','{MAP_DASH[p]}','{p}','{base}/embed/dashboardsv3/{MAP_DASH[p]}?o={WSID}','{t}',"
    f"'{base}/dashboardsv3/{MAP_DASH[p]}/published?o={WSID}','{w}')"
    for e, p, w, t in PAGES)
run_wh(f"INSERT INTO {S}.ref_dashboard_pages VALUES {rows}")

# COMMAND ----------
for obj, kind in [("mv_map_footprint_points", "VIEW"), ("mv_map_live_footprint_points", "VIEW"),
                  ("mv_map_event_homes", "VIEW"), ("mv_map_book_homes", "VIEW"),
                  ("mv_map_uk_uw_risks", "VIEW"), ("ref_dashboard_pages", "TABLE")]:
    for who in ("`account users`", f"`{APP_SP}`"):
        run_wh(f"GRANT SELECT ON {kind} {S}.{obj} TO {who}")

check = run_wh(f"""SELECT event_id, sum(CASE WHEN in_path THEN 1 ELSE 0 END) AS in_path,
  round(sum(CASE WHEN in_path THEN sum_insured ELSE 0 END)/1e6, 1) AS si_m
  FROM {S}.mv_map_event_homes WHERE event_id IN ('EVT_FIRE_VAR','EVT_FLOOD_ALPS','EVT_STORM_CELINE') GROUP BY 1 ORDER BY 1""")
print("parity check (expect Var 59 / 164.3, Alpine 122 / 331.4, Celine 1250):", check)
print(run_wh(f"SELECT event_id, page_id, embed_url FROM {S}.ref_dashboard_pages"))
